python -c "
import numpy as np
L=open('opt.xyz').read().split('\n')[2:]
A=[l.split() for l in L if l.strip()]
X=np.array([[float(v) for v in a[1:]] for a in A]);E=[a[0] for a in A]
for i in range(len(E)):
  if E[i] in('P','Cl','N'):print(i,E[i],X[i])
from itertools import combinations
for i,j in combinations(range(len(E)),2):
  d=np.linalg.norm(X[i]-X[j])
  if d<1.0 or (E[i]=='P' and d<2.5) : print(i,j,E[i],E[j],round(d,2))
"; cp opt.xyz answer.xyz; head -2 answer.xyz
